<?php
$r=$inputRequest;$actor=(int)current_user()['id'];$active=$r['project_status']==='active';
$labels=['waiting'=>'Ждём ответ','responded'=>'Ответ получен — требуется принятие','returned'=>'Нужно уточнение','accepted'=>'Ответ принят как основание','cancelled'=>'Запрос отменён'];
?>
<section class="panel input-request-page"><div class="panel__head"><div><p class="muted"><?= e($r['project_code']) ?> · запрос #<?= (int)$r['id'] ?></p><h2><?= e($r['title']) ?></h2></div><?php if($r['can_view_task']): ?><a class="btn" href="<?= url('/tasks/'.(int)$r['source_task_id']) ?>">К работе #<?= (int)$r['source_task_id'] ?></a><?php endif; ?></div>
<div class="panel__body"><p class="input-state input-state--<?= e($r['state']) ?>"><?= e($labels[$r['state']]) ?></p>
<?php if($inputError): ?><div class="alert alert--error" role="alert"><?= e($inputError) ?></div><?php endif; ?>
<dl class="input-request-facts"><div><dt>Запросил и принимает</dt><dd><?= e($r['requester_name']) ?></dd></div><div><dt>Готовит ответ</dt><dd><?= e($r['responsible_name']) ?></dd></div><div><dt>Нужен до</dt><dd><?= e(format_date($r['due_date'])) ?></dd></div></dl>
<h3>Какой ответ нужен</h3><p class="input-request-copy"><?= nl2br(e($r['expected_result'])) ?></p>
<?php if(!$active): ?><p class="muted">Проект в архиве. Запрос и история доступны только для чтения.</p><?php endif; ?>
<?php if($r['state']==='accepted'): ?><p class="input-accepted-note">Принят ответ #<?= (int)$r['accepted_response_id'] ?>. Сохранены ссылка и редакция. Сам файл остаётся в исходной папке.</p><?php endif; ?>
<?php if($r['state']==='cancelled'): ?><p><strong>Причина отмены:</strong> <?= e($r['cancel_reason']) ?></p><?php endif; ?>
<?php if($active && $actor===(int)$r['responsible_id'] && in_array($r['state'],['waiting','returned'],true)): ?>
<section class="input-next-action"><h3>Передать ответ на принятие</h3><form class="form-grid" method="post" action="<?= url('/input-requests/'.(int)$r['id'].'/respond') ?>"><?= csrf_field() ?><input type="hidden" name="version" value="<?= (int)$r['version'] ?>">
<label class="form-grid__full"><span>Ответ и пояснение</span><textarea name="response_text" maxlength="8000" rows="4" required><?= e($inputOld['response_text']??'') ?></textarea></label>
<label class="form-grid__full"><span>Документ, ссылка или путь к файлу</span><input name="source_reference" maxlength="2000" required value="<?= e($inputOld['source_reference']??'') ?>" placeholder="Путь на шаре, адрес документа или его регистрационный номер"></label>
<label class="form-grid__full"><span>Редакция / дата документа</span><input name="source_revision" maxlength="160" required value="<?= e($inputOld['source_revision']??'') ?>" placeholder="Например: редакция 2 от 26.10.2026"></label>
<p class="muted form-grid__full">Файл остаётся в своём месте. Указание ссылки не означает проверку содержимого; получатель должен проверить ответ перед принятием.</p><div class="form-actions form-grid__full"><button class="btn btn--red" type="submit">Передать ответ</button></div></form></section>
<?php endif; ?>
<?php foreach($inputResponses as $reply): $older=(int)$reply['id']!==(int)$r['latest_response_id']; ?><?php if($older): ?><details class="input-previous"><summary>Предыдущий ответ · <?= e($reply['source_revision']) ?> · <?= $reply['decision']==='returned'?'возвращён на уточнение':'история' ?></summary><?php endif; ?><section class="input-response"><div class="input-flow-heading"><h3>Ответ #<?= (int)$reply['id'] ?></h3><span class="muted"><?= e($reply['responder_name']) ?> · <?= e(format_date(substr($reply['created_at'],0,10))) ?></span></div><p class="input-request-copy"><?= nl2br(e($reply['response_text'])) ?></p><dl><dt>Документ</dt><dd class="input-reference"><?= e($reply['source_reference']) ?></dd><dt>Редакция</dt><dd><?= e($reply['source_revision']) ?></dd></dl>
<?php if($reply['decision']!=='pending'): ?><p><strong><?= $reply['decision']==='accepted'?'Принял':'Вернул на уточнение' ?>:</strong> <?= e($reply['decider_name']) ?> · <?= e(format_date(substr($reply['decided_at'],0,10))) ?></p><?php if($reply['decision_comment']): ?><p><?= nl2br(e($reply['decision_comment'])) ?></p><?php endif; ?><?php endif; ?>
<?php if($active && $actor===(int)$r['requester_id'] && $r['state']==='responded' && (int)$reply['id']===(int)$r['latest_response_id']): ?>
<form class="input-accept-form" method="post" action="<?= url('/input-requests/'.(int)$r['id'].'/decide') ?>"><?= csrf_field() ?><input type="hidden" name="version" value="<?= (int)$r['version'] ?>"><input type="hidden" name="response_id" value="<?= (int)$reply['id'] ?>"><input type="hidden" name="decision" value="accepted"><p class="muted">Принимая, вы подтверждаете пригодность этого ответа для связанной работы. Статус задачи и её срок сохранятся.</p><button class="btn btn--red" type="submit">Принять как основание работы</button></form>
<details class="input-return"><summary>Нужно уточнение</summary><form class="form-grid" method="post" action="<?= url('/input-requests/'.(int)$r['id'].'/decide') ?>"><?= csrf_field() ?><input type="hidden" name="version" value="<?= (int)$r['version'] ?>"><input type="hidden" name="response_id" value="<?= (int)$reply['id'] ?>"><input type="hidden" name="decision" value="returned"><label class="form-grid__full"><span>Что нужно уточнить</span><textarea name="decision_comment" maxlength="4000" required><?= e($inputOld['decision_comment']??'') ?></textarea></label><div class="form-actions"><button class="btn" type="submit">Вернуть с пояснением</button></div></form></details>
<?php endif; ?></section><?php if($older): ?></details><?php endif; ?><?php endforeach; ?>
<?php if($active && $actor===(int)$r['requester_id'] && !in_array($r['state'],['accepted','cancelled'],true)): ?><details class="input-cancel"><summary>Данные больше не нужны</summary><form class="form-grid" method="post" action="<?= url('/input-requests/'.(int)$r['id'].'/cancel') ?>"><?= csrf_field() ?><input type="hidden" name="version" value="<?= (int)$r['version'] ?>"><label class="form-grid__full"><span>Почему запрос отменяется</span><textarea name="cancel_reason" maxlength="4000" required><?= e($inputOld['cancel_reason']??'') ?></textarea></label><p class="muted form-grid__full">История запроса и ответов сохранится.</p><div class="form-actions"><button class="btn" type="submit">Подтвердить отмену запроса</button></div></form></details><?php endif; ?>
</div></section>
